mapper.insert:
		INSERT /*LGVATT00013.insertOsKpiStandard*/ INTO TB_PAY_KPI_OS_STANDARD
		( kpi_os_standard_no
		 ,item_no
		 ,item_name
         ,perfect_target
         ,perfect_point
         ,actual_target
         ,actual_point		
         ,criteria	
		 ,creation_user_id 					/* 사용자ID */
		 ,creation_date 					/* 등록일자 */
		 ,last_update_user_id 				/* 최종수정자ID */
		 ,last_update_date 					/* 수정일자 */
		) values
		( SQ_TB_PAY_KPI_OS_STANDARD.NEXTVAL
		 ,#{itemNo}
		 ,#{itemName}
         ,#{perfectTarget}
         ,#{perfectPoint}
         ,#{actualTarget}
         ,#{actualPoint}
         ,#{criteria}
		 ,#{applicationUserId}
		 ,trunc(sysdate)
		 ,#{applicationUserId}
		 ,trunc(sysdate)
		)

mapper.update:
UPDATE /*LGVATT00013.updateOsKpiStandard*/
       TB_PAY_KPI_OS_STANDARD 
SET    item_no                          = #{itemNo}             
     , item_name                        = #{itemName}
     , perfect_target                   = #{perfectTarget}                 
     , perfect_point                    = #{perfectPoint}
     , actual_target                    = #{actualTarget}
     , actual_point                     = #{actualPoint}
     , criteria                         = #{criteria}
     , last_update_user_id              = #{applicationUserId}            							/* 최종수정사용자아이디 */
     , last_update_date                 = trunc(sysdate)                 							/* 최종수정일자 */
WHERE  kpi_os_standard_no               = #{kpiOsStandardNo}
